    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof respondToNegotiation>>, TError,RespondToNegotiationMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof respondToNegotiation>>, TError,RespondToNegotiationMutationVariables, TContext> => {

const mutationKey = getRespondToNegotiationMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof respondToNegotiation>>, RespondToNegotiationMutationVariables> = (props) => {
          const {negotiationId,data} = props ?? {};

          return  respondToNegotiation(negotiationId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type RespondToNegotiationMutationResult = NonNullable<Awaited<ReturnType<typeof respondToNegotiation>>>
    export type RespondToNegotiationMutationBody = BodyType<NegotiationResponseInput>
    export type RespondToNegotiationMutationError = ErrorType<ForbiddenResponse | NotFoundResponse>
    export type RespondToNegotiationMutationVariables = {negotiationId: number;data: BodyType<NegotiationResponseInput>}

    /**
 * @summary Accept, reject, or counter a negotiation
 */
export const useRespondToNegotiation = <TError = ErrorType<ForbiddenResponse | NotFoundResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof respondToNegotiation>>, TError,RespondToNegotiationMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof respondToNegotiation>>,
        TError,
        RespondToNegotiationMutationVariables,
        TContext
      > => {
      return useMutation(getRespondToNegotiationMutationOptions(options));
    }

